def format_bytes(n):
    """Return a human-readable byte size string like '1.5 KB'."""
    for unit, threshold in [('TB', 1024**4), ('GB', 1024**3), ('MB', 1024**2), ('KB', 1024)]:
        if n >= threshold:
            value = n / threshold
            if value == int(value):
                return f'{int(value)} {unit}'
            return f'{value:.1f} {unit}'
    return f'{n} B'
